import{_ as l,a0 as s,w as p,s as o,ao as u,I as r,x as n,a1 as t,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux 大爆炸：一个内核，无数发行版 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 大爆炸：一个内核，无数发行版 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 大爆炸：一个内核，无数发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 大爆炸：一个内核，无数发行版 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170427 Linux s Big Bang One Kernel Countless Distros","title":"Linux 大爆炸：一个内核，无数发行版","tag":"201706","desc":""},"relativePath":"201706/20170427 Linux s Big Bang One Kernel Countless Distros.md","filePath":"[post].md"}'),d={name:"201706/20170427 Linux s Big Bang One Kernel Countless Distros.md"};function x(h,a,L,m,T,f){const i=s("Link");return p(),o("div",null,[a[13]||(a[13]=u('<h1 id="linux-大爆炸-一个内核-无数发行版" tabindex="-1">Linux 大爆炸：一个内核，无数发行版 <a class="header-anchor" href="#linux-大爆炸-一个内核-无数发行版" aria-label="Permalink to “Linux 大爆炸：一个内核，无数发行版”">​</a></h1><p><img src="http://www.linuxinsider.com/article_images/story_graphics_xlarge/xl-2017-linus-torvalds-1.jpg" alt="linus-torvalds"></p><p>即使你是一个 Linux 新人，你可能也已经知道它不是一个单一的、整体的操作系统，而是一群项目。这个星座中不同的“星”组成了“发行版”。每个都提供了自己的 Linux 模式。</p><p>感谢这一系列发行版所提供的多种选择，这有助于了解 Linux 如何开始并随后激增的。因此，这里会简要介绍一下 Linux 的历史。</p><h3 id="linus-torvalds-内核构建者" tabindex="-1">Linus Torvalds，内核构建者 <a class="header-anchor" href="#linus-torvalds-内核构建者" aria-label="Permalink to “Linus Torvalds，内核构建者”">​</a></h3><p>大多数熟悉 Linux 的人都已经听说过它的创建者 Linus Torvalds （上图中的人），但是并不知道他最初为何创建它。在 1991 年，Torvalds 还是一名在芬兰学习计算机的大学生。作为一个独立的个人项目，他希望为他的独特硬件创建一个类 Unix 内核。</p><p>“内核”是操作系统的一部分，它介乎于操作系统和硬件之间，通过其固件进行协调。本质上，它是系统的核心。开发内核不是一个小工程，但是 Torvalds 渴望挑战，并且发现他自己有这个罕见的技能。</p><p>由于他刚接触内核，他希望得到其他人的帮助来确保他走在正确的轨道上，因此他通过在早期的互联网论坛 Usenet 发布他的内核代码，并征求了老牌的老手的经验。然后贡献者就涌来了。</p><p>在建立了一个对论坛提交的补丁进行审查以及选择性地集成它们的流程后，Torvalds 意识到他聚集起了一个非正式的团队。在项目发展之后，它很快成为了一个比较正式的开发团队。</p><h3 id="richard-stallman-的角色" tabindex="-1">Richard Stallman 的角色 <a class="header-anchor" href="#richard-stallman-的角色" aria-label="Permalink to “Richard Stallman 的角色”">​</a></h3><p>虽然 Torvalds 以及他的团建创造了 Linux 内核，但是没有 Richard Stallman 的工作也不会有随后 Linux 众多发行版的传播，Richard 在十年之前发起了一个自由软件运动。</p><p>受到许多核心 Unix 程序和系统功能缺乏透明度的阻挠，Stallman 决定自己编写一个，与任何想要它的人自由共享源代码，并且开放提交。他创造了许多核心程序的主体，并在 1983 年发布，统称为 “GNU 项目”。</p><p>没有它们，内核不会有那么多的用量。基于 Linux 的操作系统的早期设计人员很乐意将 GNU 工具集成到他们的项目中。</p><p>不同的团队开始出现 - 每个团队都有自己的计算功能和架构的理念。他们将 Linux 内核、GNU 实用程序和他们自己的原始软件结合在一起，然而“发行”了 Linux 操作系统的变体。</p><h3 id="服务器发行版" tabindex="-1">服务器发行版 <a class="header-anchor" href="#服务器发行版" aria-label="Permalink to “服务器发行版”">​</a></h3><p>每个发行版有它自己的设计逻辑和目的，但是要了解它们的细微差别，需要了解上游和下游开发人员之间的区别。“上游开发人员”负责实际创建项目并发布，以供个人下载或将其包含在其他项目中。相比之下，“下游开发人员”或“软件包维护人员”是指每个发布上游程序的人员，他们对每个上游程序的版本进行调整以适应下游项目的使用情况。</p><p>虽然大多数 Linux 发行版包含一些（自己的）原生项目，但大部分发行版开发主要是对 Linux 内核、GNU 工具和庞大的用户程序生态系统的“下游”工作。</p><p>许多发行通过优化特定使用场景来彰显它们的特征。例如，某些项目被设计作为服务器运行。为部署服务器而量身定制的发行版通常会避开上游项目中快速推出的最新功能，而倾向于发布一个经过彻底测试的、基础的基本软件，系统管理员可以依靠它来顺利运行。</p><p>针对服务器的发行版的的开发团队经常很大，并且有富有经验的程序员可以为每个版本提供多年的支持。</p><h3 id="桌面发行版" tabindex="-1">桌面发行版 <a class="header-anchor" href="#桌面发行版" aria-label="Permalink to “桌面发行版”">​</a></h3><p>也有很多的发行版针对桌面用户。事实上，一些知名的发行版通过提供简单的安装以及直观的界面来与商业的操作系统竞争。这些发行版通常包含了大量的软件仓库，它包含了用户可以想到的每个软件，这样用户可以定制它们自己的系统。</p><p>由于可用性是关键，他们可能会投入部门大量的员工来创建一个特征鲜明的、发行版特定的桌面，或调整已有的桌面以适应其设计理念。以用户为中心的发行版往往会加快其下游开发时间表，有助于及时为用户提供新功能。</p><p>“滚动发布”项目，这是一种桌面发行版的子集，其被设计成紧跟潮流。滚动发布项目的包维护人员在为每个上游程序完成调整后分别发布其新版本，而不是等待所需的上游程序的开发达到某一特定的节点，然后将其集成到单个版本中。</p><p>这种方法的一个优点是安全性，因为其关键补丁的发布将比非滚动发行版更快。另一个好处是新功能立即可用，不然用户需要等待才行。滚动发布的缺点是需要更多的人工干预和仔细维护，因为某些升级可能会与其他升级相冲突从而破坏系统。</p><h3 id="嵌入式系统" tabindex="-1">嵌入式系统 <a class="header-anchor" href="#嵌入式系统" aria-label="Permalink to “嵌入式系统”">​</a></h3><p>另外一个 Linux 发行版类别是“嵌入式系统”，它被极致裁剪（相对与服务器和桌面发行版）来适应特定的使用情况。</p><p>我们经常会忘记那些连接到因特网的任何东西，或者比一个简单的计算器复杂的东西，都是计算机。而计算机需要操作系统。因为 Linux 是自由的并且高度模块化，所以它通常是硬件厂商的选择。</p><p>在大多数情况下，如果你看见一台智能电视、一台连接互联网的照相机、甚至是一辆车，你看到的都是 Linux 设备。特别是每部非 iPhone 的智能手机都运行着不同的嵌入式 Linux。</p><h3 id="linux-现场版" tabindex="-1">Linux 现场版 <a class="header-anchor" href="#linux-现场版" aria-label="Permalink to “Linux 现场版”">​</a></h3><p>最后，有一些 Linux 发行版并不需要永久性地安装在计算机中，而是驻留在 USB 记忆棒上，并允许在其它的计算机上启动它们，而无需计算机硬盘。</p><p>这些 “现场版（live）” 的系统可以被优化来执行一些任务。从修复损坏的系统到进行安全评估到高度安全地浏览因特网。</p><p>由于这些 现场版 Linux 发行版通常针对解决特定的问题，因此它们一般都包含特定的工具，像磁盘分析和恢复程序、网络监控程序和加密工具。它们还占用很小的空间，因此它们可以快速启动。</p><h3 id="你如何选择" tabindex="-1">你如何选择？ <a class="header-anchor" href="#你如何选择" aria-label="Permalink to “你如何选择？”">​</a></h3><p>这绝不是 Linux 发行版类型的全面列表，但它应该可以让你大致了解 Linux 生态系统的范围和多样化了。</p><p>在每个类别下都有许多选择，因此你会如何选择一个最能符合你需求的版本呢？</p><p>一种方式是试验。在 Linux 社区中，来回尝试不同的发行版，或者为用户根据他们的需求在不同的机器上运行不同的发行版，这都很常见。</p><p>在将来的文章中，我会展示每种类型发行版的几个例子，以便你可以自己尝试，并开始探索最喜欢的发行版的旅程。</p><hr><p>作者简介：</p><p>自 2017 年以来 Jonathan Terrasi 一直是 ECT 新闻网的专栏作家。他的主要兴趣是计算机安全（特别是 Linux 桌面），加密和分析政治和时事。他是全职自由作家和音乐家。他的背景包括在芝加哥委员会发表的保卫人权法案文章中提供技术评论和分析。</p><hr>',41)),r("p",null,[a[1]||(a[1]=n("via: ",-1)),t(i,{href:"http://www.linuxinsider.com/story/84489.html"},{default:e(()=>[...a[0]||(a[0]=[n("http://www.linuxinsider.com/story/84489.html",-1)])]),_:1})]),r("p",null,[a[5]||(a[5]=n("作者：",-1)),t(i,{href:"http://www.linuxinsider.com/story/84489.html?rss=1#searchbyline"},{default:e(()=>[...a[2]||(a[2]=[n("Jonathan Terrasi",-1)])]),_:1}),a[6]||(a[6]=n(" 译者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:e(()=>[...a[3]||(a[3]=[n("geekpi",-1)])]),_:1}),a[7]||(a[7]=n(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...a[4]||(a[4]=[n("wxy",-1)])]),_:1})]),r("p",null,[a[10]||(a[10]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[8]||(a[8]=[n("LCTT",-1)])]),_:1}),a[11]||(a[11]=n(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...a[9]||(a[9]=[n("Linux中国",-1)])]),_:1}),a[12]||(a[12]=n(" 荣誉推出",-1))])])}const v=l(d,[["render",x]]);export{b as __pageData,v as default};
